			name: "LabelHpaMinReplicas with 0 value",
			args: args{
				service: &kobject.ServiceConfig{
					Labels: map[string]string{
						compose.LabelHpaMinReplicas: "0",
						compose.LabelHpaMaxReplicas: "10",
						compose.LabelHpaCPU:         "50",
