			name: "LabelHpaMinReplicas with error value",
			args: args{
				service: &kobject.ServiceConfig{
					Labels: map[string]string{
						compose.LabelHpaMinReplicas: "cannot transform",
						compose.LabelHpaMaxReplicas: "10",
