						Name: "memory",
						Target: hpa.MetricTarget{
							Type:               hpa.UtilizationMetricType,
							AverageUtilization: &valueMemoryFixed,
						},
					},
				},
			},
		},
		{
			name: "cpu and memory",
			args: args{
				hpaValues: HpaValues{
