func Test_getHpaValue(t *testing.T) {
	type args struct {
		service      *kobject.ServiceConfig
		label        string
		defaultValue int32
	}
	tests := []struct {
		name string
		args args
		want int32
	}{
		// LabelHpaMinReplicas
		{
			name: "LabelHpaMinReplicas with 1 value",
			args: args{
				service: &kobject.ServiceConfig{
					Labels: map[string]string{
						compose.LabelHpaMinReplicas: "1",
