			},
			wantUseConfigMap: true,
			wantReadonly:     true,
			wantSkip:         false,
		},
		{
			name: "docker sock",
			args: args{
				filePath: "/var/run/docker.sock",
			},
			wantUseConfigMap: false,
			wantReadonly:     false,
			wantSkip:         true,
		},
		{
			name: "dir sys",
			args: args{
