			if gotReadonly != tt.wantReadonly {
				t.Errorf("isConfigFile() gotReadonly = %v, want %v", gotReadonly, tt.wantReadonly)
			}
			if gotSkip != tt.wantSkip {
				t.Errorf("isConfigFile() gotSkip = %v, want %v", gotSkip, tt.wantSkip)
			}
		})
	}
}

